export type RafflePluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function raffleProgram() {
  return <T extends RafflePluginRequirements>(
    client: T,
  ): Omit<T, "raffle"> & { raffle: RafflePlugin } => {
    return extendClient(client, {
      raffle: <RafflePlugin>{
        accounts: {
          poolTypeCounter: addSelfFetchFunctions(
            client,
            getPoolTypeCounterCodec(),
          ),
          privatePool: addSelfFetchFunctions(client, getPrivatePoolCodec()),
          protocolConfig: addSelfFetchFunctions(
            client,
            getProtocolConfigCodec(),
          ),
          publicPool: addSelfFetchFunctions(client, getPublicPoolCodec()),
          redeemedCode: addSelfFetchFunctions(client, getRedeemedCodeCodec()),
          ticketBatch: addSelfFetchFunctions(client, getTicketBatchCodec()),
          whitelisted: addSelfFetchFunctions(client, getWhitelistedCodec()),
        },
        instructions: {
          buyTicketPrivate: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getBuyTicketPrivateInstructionAsync(input),
            ),
          buyTicketPublic: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getBuyTicketPublicInstruction(input),
            ),
          closeEmptyPrivatePool: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCloseEmptyPrivatePoolInstruction(input),
            ),
          commitDrawPrivate: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCommitDrawPrivateInstruction(input),
            ),
          commitDrawPublic: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCommitDrawPublicInstruction(input),
            ),
          createPrivatePool: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreatePrivatePoolInstructionAsync(input),
            ),
          initializeProtocol: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializeProtocolInstructionAsync(input),
            ),
          initializePublicPool: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializePublicPoolInstruction({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          redeemInviteCodeOneTicket: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRedeemInviteCodeOneTicketInstruction(input),
            ),
          redeemInviteCodeWhitelist: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRedeemInviteCodeWhitelistInstructionAsync(input),
            ),
          reopenPublicPool: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getReopenPublicPoolInstruction({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          retryDrawPublic: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRetryDrawPublicInstruction(input),
            ),
          settleDrawPrivate: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSettleDrawPrivateInstructionAsync(input),
            ),
          settleDrawPublic: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSettleDrawPublicInstructionAsync(input),
            ),
        },
        pdas: {
          whitelisted: findWhitelistedPda,
          pool: findPoolPda,
          config: findConfigPda,
        },
      },
    });
  };
}

type MakeOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
